    public async Task<DashboardConfiguration?> GetDashboardAsync(string layoutId,CancellationToken token=default){await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteCommand q=c.CreateCommand();q.CommandText="SELECT Id,LayoutId,Name,IsDefault,HeroEnabled,CardDensity,RowSpacing,ShowStatusBar,ShowFooterHints,CreatedAtUtc,UpdatedAtUtc FROM DashboardConfigurations WHERE LayoutId=$layout ORDER BY IsDefault DESC LIMIT 1;";q.Parameters.AddWithValue("$layout",layoutId);await using SqliteDataReader r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?Dashboard(r):null;}
