    public async Task ReplaceRowsAsync(string dashboardId,IReadOnlyList<DashboardRowConfiguration> rows,CancellationToken token=default){await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteTransaction t=(SqliteTransaction)await c.BeginTransactionAsync(token);try{await Exec(c,t,"DELETE FROM DashboardRows WHERE DashboardConfigurationId=$id;",token,("$id",dashboardId));foreach(DashboardRowConfiguration v in rows)await InsertRow(c,t,v,token);await t.CommitAsync(token);}catch{await t.RollbackAsync(token);throw;}}

