    public async Task<IReadOnlyList<CollectionDefinition>> GetCollectionsAsync(CancellationToken token=default){await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteCommand q=c.CreateCommand();q.CommandText="SELECT Id,Name,Description,CollectionType,IconKey,CoverAssetPath,ParentCollectionId,SortOrder,Hidden,MatchMode,CreatedAtUtc,UpdatedAtUtc FROM Collections ORDER BY SortOrder,Name;";await using SqliteDataReader r=await q.ExecuteReaderAsync(token);List<CollectionDefinition> values=[];while(await r.ReadAsync(token))values.Add(Collection(r));return values;}
