    public async Task<IReadOnlyList<ThemeDefinition>> GetCustomThemesAsync(CancellationToken token=default){await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteCommand q=c.CreateCommand();q.CommandText="SELECT Id,Name,Description,ThemeType,AccentColor,SecondaryAccentColor,BackgroundType,BackgroundPath,BackgroundStretch,BackgroundBlurAmount,BackgroundDarkeningOverlay,BackgroundOpacity,BackgroundManagedCopy,CardShape,SurfaceOpacity,BlurEnabled,AnimationIntensity,SoundPackId,BuiltIn,Enabled,Version,AuthorDisplayName,MinimumNexaStationVersion FROM Themes ORDER BY Name;";await using SqliteDataReader r=await q.ExecuteReaderAsync(token);List<ThemeDefinition> values=[];while(await r.ReadAsync(token)){BackgroundDefinition b=new((BackgroundType)r.GetInt32(6),N(r,7),(BackgroundStretch)r.GetInt32(8),r.GetInt32(9),r.GetDouble(10),r.GetDouble(11),r.GetInt32(12)!=0);values.Add(new(r.GetString(0),r.GetString(1),N(r,2)??string.Empty,(ThemeType)r.GetInt32(3),r.GetString(4),N(r,5),b,(CardShape)r.GetInt32(13),r.GetDouble(14),r.GetInt32(15)!=0,(AnimationIntensity)r.GetInt32(16),N(r,17),r.GetInt32(18)!=0,r.GetString(20),r.GetString(21),r.GetString(22),r.GetInt32(19)!=0));}return values;}
