    public async Task<string> SaveExportBackupAsync(string json,CancellationToken token=default){string id=Guid.NewGuid().ToString("N");await using SqliteConnection c=await factory.OpenAsync(token);await Exec(c,null,"INSERT INTO InterfaceConfigurationExports(Id,FormatVersion,ConfigurationJson,CreatedAtUtc,Purpose) VALUES($id,1,$json,$at,'Backup');",token,("$id",id),("$json",json),("$at",D(DateTime.UtcNow)));return id;}
    public async Task ApplySnapshotAsync(InterfaceConfigurationSnapshot snapshot,CancellationToken token=default)
    {
        await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteTransaction t=(SqliteTransaction)await c.BeginTransactionAsync(token);try{await Clear(c,t,token);foreach(DashboardConfiguration v in snapshot.Dashboards)await InsertDashboard(c,t,v,token);foreach(DashboardRowConfiguration v in snapshot.Rows)await InsertRow(c,t,v,token);foreach(PinnedItem v in snapshot.Pins)await InsertPin(c,t,v,token);foreach(CollectionDefinition v in snapshot.Collections)await InsertCollection(c,t,v,token);foreach(CollectionItem v in snapshot.CollectionItems)await InsertItem(c,t,v,token);foreach(SmartCollectionRule v in snapshot.SmartRules)await InsertRule(c,t,v,token);if(snapshot.CustomTheme is not null)await InsertTheme(c,t,snapshot.CustomTheme,token);await UpsertSetting(c,t,"Interface.LayoutId",JsonSerializer.Serialize(snapshot.LayoutId),token);await UpsertSetting(c,t,"Interface.ThemeId",JsonSerializer.Serialize(snapshot.ThemeId),token);await UpsertSetting(c,t,"Interface.SoundPackId",JsonSerializer.Serialize(snapshot.SoundPackId),token);await UpsertSetting(c,t,"Interface.SoundVolume",JsonSerializer.Serialize(snapshot.SoundVolume),token);await UpsertSetting(c,t,"Interface.Performance",JsonSerializer.Serialize(snapshot.Performance),token);await t.CommitAsync(token);}catch{await t.RollbackAsync(token);throw;}
    }
    public async Task ClearInterfaceCustomizationAsync(CancellationToken token=default){await using SqliteConnection c=await factory.OpenAsync(token);await using SqliteTransaction t=(SqliteTransaction)await c.BeginTransactionAsync(token);try{await Clear(c,t,token);await t.CommitAsync(token);}catch{await t.RollbackAsync(token);throw;}}

