    private static Task InsertCollection(SqliteConnection c,SqliteTransaction? t,CollectionDefinition v,CancellationToken token)=>Exec(c,t,"INSERT INTO Collections VALUES($id,$name,$description,$type,$icon,$cover,$parent,$sort,$hidden,$match,$created,$updated) ON CONFLICT(Id) DO UPDATE SET Name=excluded.Name,Description=excluded.Description,CollectionType=excluded.CollectionType,IconKey=excluded.IconKey,CoverAssetPath=excluded.CoverAssetPath,ParentCollectionId=excluded.ParentCollectionId,SortOrder=excluded.SortOrder,Hidden=excluded.Hidden,MatchMode=excluded.MatchMode,UpdatedAtUtc=excluded.UpdatedAtUtc;",token,("$id",v.Id),("$name",v.Name),("$description",v.Description),("$type",(int)v.CollectionType),("$icon",v.IconKey),("$cover",v.CoverAssetPath),("$parent",v.ParentCollectionId),("$sort",v.SortOrder),("$hidden",B(v.Hidden)),("$match",(int)v.MatchMode),("$created",D(v.CreatedAtUtc)),("$updated",D(v.UpdatedAtUtc)));
