    private static Task InsertRule(SqliteConnection c,SqliteTransaction? t,SmartCollectionRule v,CancellationToken token)=>Exec(c,t,"INSERT INTO SmartCollectionRules VALUES($id,$collection,$group,$field,$operator,$value,$sort,$created,$updated);",token,("$id",v.Id),("$collection",v.CollectionId),("$group",v.RuleGroup),("$field",(int)v.Field),("$operator",(int)v.Operator),("$value",v.ValueJson),("$sort",v.SortOrder),("$created",D(v.CreatedAtUtc)),("$updated",D(v.UpdatedAtUtc)));
