    private static string? N(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static int B(bool v)=>v?1:0;private static string D(DateTime v)=>v.ToUniversalTime().ToString("O",CultureInfo.InvariantCulture);private static DateTime Date(SqliteDataReader r,int i)=>DateTime.Parse(r.GetString(i),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind);
